   741  /*
   742   * 'delete_stack()' - Free memory used by a stack.
   743   */
   744
   745  static void
   746  delete_stack(_cups_ps_stack_t *st)      /* I - Stack */
   747  {
   748    free(st->objs);
   749    free(st);
   750  }
